I couldn't create files or run anything in this session, so the code is below for you to paste in. It's a **separable Gaussian blur** that runs as two compute passes.

### Passes

| Pass | Reads | Writes | Result is in |
| --- | --- | --- | --- |
| 1, horizontal (`dir = (1,0)`) | `src` | `tmp` | `tmp` |
| 2, vertical (`dir = (0,1)`) | `tmp` | `dst` | `dst` |
| copy | `dst` | canvas texture | canvas |

Both dispatches go in one compute pass. Dispatches in a pass see each other's writes in order, so pass 2 reads what pass 1 finished writing. Splitting the blur into a horizontal and a vertical pass costs `2·(2r+1)` texture reads per pixel instead of `(2r+1)²`.

### `blur.wgsl`

```wgsl
struct Params {
  dir: vec2i,    // offset 0: (1,0) horizontal, (0,1) vertical
  radius: i32,   // offset 8
  sigma: f32,    // offset 12. Struct size is 16.
}

override WG_X: u32 = 8;
override WG_Y: u32 = 8;

@group(0) @binding(0) var src: texture_2d<f32>;
@group(0) @binding(1) var dst: texture_storage_2d<rgba8unorm, write>;
@group(0) @binding(2) var<uniform> params: Params;

@compute @workgroup_size(WG_X, WG_Y)
fn blur(@builtin(global_invocation_id) gid: vec3u) {
  let size = textureDimensions(src);
  // The dispatch is rounded up, so edge workgroups run past the image.
  if (gid.x >= size.x || gid.y >= size.y) { return; }

  let p = vec2i(gid.xy);
  let maxP = vec2i(size) - 1;
  let k = -0.5 / (params.sigma * params.sigma);

  var sum = vec4f(0.0);
  var wsum = 0.0;
  for (var i = -params.radius; i <= params.radius; i++) {
    let w = exp(f32(i * i) * k);
    // Clamp to edge so border pixels don't darken.
    let q = clamp(p + params.dir * i, vec2i(0), maxP);
    sum += textureLoad(src, q, 0) * w;
    wsum += w;
  }
  textureStore(dst, p, sum / wsum);
}
```

### `blur.ts`

```ts
const WG = 8
const MAX_RADIUS = 64 // A huge kernel on a big image can trip the GPU timeout and lose the device.
const PARAMS_SIZE = 16

export type Blur = {
  run(image: ImageBitmap, radius: number): void
  destroy(): void
}

export async function createBlur(
  device: GPUDevice,
  canvas: HTMLCanvasElement,
  shaderCode: string,
): Promise<Blur> {
  const module = device.createShaderModule({ label: 'blur.shader', code: shaderCode })

  const bindGroupLayout = device.createBindGroupLayout({
    label: 'blur.bgl',
    entries: [
      { binding: 0, visibility: GPUShaderStage.COMPUTE, texture: { sampleType: 'float' } },
      {
        binding: 1,
        visibility: GPUShaderStage.COMPUTE,
        storageTexture: { access: 'write-only', format: 'rgba8unorm' },
      },
      { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: 'uniform' } },
    ],
  })

  // Rejects with a GPUPipelineError (WGSL errors included) rather than raising a device error.
  const pipeline = await device.createComputePipelineAsync({
    label: 'blur.pipeline',
    layout: device.createPipelineLayout({ label: 'blur.layout', bindGroupLayouts: [bindGroupLayout] }),
    compute: { module, entryPoint: 'blur', constants: { WG_X: WG, WG_Y: WG } },
  })

  const paramsH = device.createBuffer({
    label: 'blur.params.horizontal',
    size: PARAMS_SIZE,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  })
  const paramsV = device.createBuffer({
    label: 'blur.params.vertical',
    size: PARAMS_SIZE,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  })

  const context = canvas.getContext('webgpu')
  if (!context) throw new Error('Could not get a webgpu canvas context')
  // Canvas and dst are both rgba8unorm, so the result can be copied straight in without a render pass.
  context.configure({
    device,
    format: 'rgba8unorm',
    usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.COPY_DST,
    alphaMode: 'premultiplied',
  })

  function writeParams(buffer: GPUBuffer, dx: number, dy: number, radius: number, sigma: number) {
    const data = new ArrayBuffer(PARAMS_SIZE)
    new Int32Array(data, 0, 3).set([dx, dy, radius])
    new Float32Array(data, 12, 1)[0] = sigma
    device.queue.writeBuffer(buffer, 0, data)
  }

  function run(image: ImageBitmap, radius: number) {
    const w = image.width
    const h = image.height
    const max = device.limits.maxTextureDimension2D
    if (w > max || h > max) throw new Error(`Image ${w}x${h} exceeds maxTextureDimension2D ${max}`)

    const r = Math.max(0, Math.min(MAX_RADIUS, Math.round(radius)))
    const sigma = Math.max(r / 3, 0.5) // About 99.7% of the Gaussian's weight falls within 3 sigma.
    writeParams(paramsH, 1, 0, r, sigma)
    writeParams(paramsV, 0, 1, r, sigma)

    canvas.width = w
    canvas.height = h

    const src = device.createTexture({
      label: 'blur.src',
      size: [w, h],
      format: 'rgba8unorm',
      // copyExternalImageToTexture requires RENDER_ATTACHMENT and COPY_DST.
      usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST | GPUTextureUsage.RENDER_ATTACHMENT,
    })
    const tmp = device.createTexture({
      label: 'blur.tmp',
      size: [w, h],
      format: 'rgba8unorm',
      usage: GPUTextureUsage.STORAGE_BINDING | GPUTextureUsage.TEXTURE_BINDING,
    })
    const dst = device.createTexture({
      label: 'blur.dst',
      size: [w, h],
      format: 'rgba8unorm',
      usage: GPUTextureUsage.STORAGE_BINDING | GPUTextureUsage.COPY_SRC,
    })

    // Premultiply so transparent pixels don't bleed their RGB into the blur.
    device.queue.copyExternalImageToTexture(
      { source: image },
      { texture: src, premultipliedAlpha: true },
      [w, h],
    )

    const bindH = device.createBindGroup({
      label: 'blur.bind.horizontal',
      layout: bindGroupLayout,
      entries: [
        { binding: 0, resource: src.createView() },
        { binding: 1, resource: tmp.createView() },
        { binding: 2, resource: { buffer: paramsH } },
      ],
    })
    const bindV = device.createBindGroup({
      label: 'blur.bind.vertical',
      layout: bindGroupLayout,
      entries: [
        { binding: 0, resource: tmp.createView() },
        { binding: 1, resource: dst.createView() },
        { binding: 2, resource: { buffer: paramsV } },
      ],
    })

    const encoder = device.createCommandEncoder({ label: 'blur.encoder' })
    const pass = encoder.beginComputePass({ label: 'blur.pass' })
    pass.setPipeline(pipeline)
    const gx = Math.ceil(w / WG)
    const gy = Math.ceil(h / WG)
    pass.setBindGroup(0, bindH)
    pass.dispatchWorkgroups(gx, gy)
    pass.setBindGroup(0, bindV)
    pass.dispatchWorkgroups(gx, gy)
    pass.end()

    encoder.copyTextureToTexture({ texture: dst }, { texture: context!.getCurrentTexture() }, [w, h])
    device.queue.submit([encoder.finish()])

    // Safe right after submit: destruction waits for the submitted work to finish.
    src.destroy()
    tmp.destroy()
    dst.destroy()
  }

  return {
    run,
    destroy() {
      paramsH.destroy()
      paramsV.destroy()
      context.unconfigure()
      device.destroy()
    },
  }
}
```

### `main.ts`: setup, errors, device loss, fallback

```ts
import { createBlur } from './blur'

const RADIUS = 12
let attempts = 0

function fallback(canvas: HTMLCanvasElement, image: ImageBitmap, radius: number, reason: string) {
  console.warn(`[blur] WebGPU unavailable (${reason}), using Canvas 2D filter`)
  canvas.width = image.width
  canvas.height = image.height
  const ctx = canvas.getContext('2d')!
  ctx.filter = `blur(${radius / 3}px)` // CSS blur radius is the standard deviation
  ctx.drawImage(image, 0, 0)
}

async function start(canvas: HTMLCanvasElement, image: ImageBitmap) {
  if (!navigator.gpu) return fallback(canvas, image, RADIUS, 'navigator.gpu missing')
  const adapter = await navigator.gpu.requestAdapter() // Always a new adapter, including after a loss
  if (!adapter) return fallback(canvas, image, RADIUS, 'no adapter')

  let device: GPUDevice
  try {
    device = await adapter.requestDevice({ label: 'blur.device' })
  } catch (e) {
    return fallback(canvas, image, RADIUS, `requestDevice failed: ${e}`)
  }

  device.addEventListener('uncapturederror', (e) => {
    console.error('[blur] GPU error:', (e as GPUUncapturedErrorEvent).error.message)
  })
  device.lost.then((info) => {
    if (info.reason === 'destroyed') return
    console.warn('[blur] device lost:', info.message)
    if (++attempts > 3) return console.error('[blur] giving up after repeated device loss')
    void start(canvas, image) // Everything is rebuilt from the CPU-side ImageBitmap
  })

  const code = await (await fetch(new URL('./blur.wgsl', import.meta.url))).text()
  try {
    const blur = await createBlur(device, canvas, code)
    blur.run(image, RADIUS)
  } catch (e) {
    console.error('[blur] pipeline creation failed:', e)
  }
}

const canvas = document.querySelector('canvas')!
const image = await createImageBitmap(await (await fetch('/photo.jpg')).blob())
await start(canvas, image)
```

### Notes

- **Gamma:** the blur runs on sRGB-encoded values in `rgba8unorm`, so edges between high-contrast areas come out slightly too dark. A storage texture can't use `rgba8unorm-srgb`. For a physically correct blur, decode to linear in the shader and use an `rgba16float` intermediate.
- **Speed:** each pixel reads `2r+1` texels per pass. For large radii, a version that loads a tile plus border into `var<workgroup>` memory first is faster. Measure before adding that complexity.
- **Workgroup size:** 8×8 is an `override`, set from TypeScript through `constants`. It's a starting point, not a measured best value.

