```ts
// compute.test.ts
import { create, globals } from 'webgpu'
import { afterAll, afterEach, beforeAll, describe, expect, test } from 'vitest'

Object.assign(globalThis, globals) // GPUBufferUsage, GPUMapMode, ...

// Replace with your shader, e.g. `import shaderCode from '../src/double.wgsl?raw'`
const WORKGROUP_SIZE = 64
const shaderCode = /* wgsl */ `
  @group(0) @binding(0) var<storage, read>       input:  array<f32>;
  @group(0) @binding(1) var<storage, read_write> output: array<f32>;

  @compute @workgroup_size(${WORKGROUP_SIZE})
  fn main(@builtin(global_invocation_id) id: vec3u) {
    if (id.x >= arrayLength(&input)) { return; } // bounds check
    output[id.x] = input[id.x] * 2.0;
  }
`

const adapter = await create([]).requestAdapter()
let device: GPUDevice
const gpuErrors: string[] = []

async function runShader(input: Float32Array): Promise<Float32Array> {
  const module = device.createShaderModule({ label: 'double shader', code: shaderCode })
  const info = await module.getCompilationInfo()
  const compileErrors = info.messages.filter((m) => m.type === 'error')
  if (compileErrors.length) {
    throw new Error(compileErrors.map((m) => `${m.lineNum}:${m.linePos} ${m.message}`).join('\n'))
  }

  const pipeline = await device.createComputePipelineAsync({
    label: 'double pipeline',
    layout: 'auto',
    compute: { module, entryPoint: 'main' },
  })

  const size = input.byteLength
  const inputBuf = device.createBuffer({
    label: 'input',
    size,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
  })
  const outputBuf = device.createBuffer({
    label: 'output',
    size,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC,
  })
  const readBuf = device.createBuffer({
    label: 'readback',
    size,
    usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
  })
  device.queue.writeBuffer(inputBuf, 0, input)

  const bindGroup = device.createBindGroup({
    label: 'double bind group',
    layout: pipeline.getBindGroupLayout(0),
    entries: [
      { binding: 0, resource: { buffer: inputBuf } },
      { binding: 1, resource: { buffer: outputBuf } },
    ],
  })

  const encoder = device.createCommandEncoder({ label: 'double encoder' })
  const pass = encoder.beginComputePass({ label: 'double pass' })
  pass.setPipeline(pipeline)
  pass.setBindGroup(0, bindGroup)
  pass.dispatchWorkgroups(Math.ceil(input.length / WORKGROUP_SIZE)) // round up
  pass.end()
  encoder.copyBufferToBuffer(outputBuf, 0, readBuf, 0, size)
  device.queue.submit([encoder.finish()])

  await readBuf.mapAsync(GPUMapMode.READ)
  const result = new Float32Array(readBuf.getMappedRange().slice(0))
  readBuf.unmap()
  inputBuf.destroy()
  outputBuf.destroy()
  readBuf.destroy()
  return result
}

describe.skipIf(!adapter)('double compute shader', () => {
  beforeAll(async () => {
    device = await adapter!.requestDevice({ label: 'test device' })
    // Throwing inside a listener would not fail the test. Collect the errors, then assert.
    device.addEventListener('uncapturederror', (e) => {
      gpuErrors.push((e as GPUUncapturedErrorEvent).error.message)
    })
  })
  afterEach(() => expect(gpuErrors.splice(0)).toEqual([]))
  afterAll(() => device?.destroy())

  test('doubles each element', async () => {
    const input = new Float32Array([1, 2, 3, -4.5, 0])
    expect(Array.from(await runShader(input))).toEqual([2, 4, 6, -9, 0])
  })

  test('covers the partial last workgroup', async () => {
    const n = 1000 // not a multiple of 64 on purpose
    const input = Float32Array.from({ length: n }, (_, i) => i)
    const out = await runShader(input)
    expect(out[n - 1]).toBe((n - 1) * 2)
    expect(out.every((v, i) => v === i * 2)).toBe(true)
  })

  test('handles exactly one workgroup', async () => {
    const input = new Float32Array(WORKGROUP_SIZE).fill(3)
    expect((await runShader(input)).every((v) => v === 6)).toBe(true)
  })
})
```

How it catches failures (WebGPU usually reports errors instead of throwing):
- **Compile errors:** `getCompilationInfo()` turns shader errors into a thrown error that includes line numbers.
- **Validation errors:** these never throw, so the `uncapturederror` listener collects them, and `afterEach` fails the test if any appeared.
- **Partial last workgroup:** the 1000-element test catches a dispatch count that was rounded down, or a missing bounds check.
- **No GPU:** `describe.skipIf(!adapter)` skips the suite with a clear reason on CI machines without a GPU, instead of failing.

Things to change when you plug in your shader:
- **Real code path:** if your app already has a function that creates the pipeline and dispatches the work, import and call it instead of `runShader`. That way the test covers the code you actually ship.
- **Structs:** if your shader reads structs from the CPU, get the byte offsets from the skill's layout script (`node scripts/wgsl-layout.mjs your.wgsl`) rather than counting by hand. `vec3` is 16-byte aligned, which is a common source of garbled values.
- **Float results:** if results involve float math beyond exact operations, use `toBeCloseTo` instead of exact equality.
- **Version pin:** pin the `webgpu` version, because it follows Dawn's changes.

