  th { color: var(--text-secondary); font-weight: 500; }
  td { color: var(--text-primary); }
</style>
</head>
<body>
<figure class="viz-root" id="viz">
  <h2 id="chart-title">Monthly signups</h2>
  <p class="subtitle">New accounts per month, 2026</p>
  <canvas id="chart" tabindex="0" role="img"
          aria-labelledby="chart-title" aria-describedby="chart-desc"></canvas>
  <div class="tooltip" id="tooltip" role="status" aria-live="polite"></div>
  <details>
    <summary>View as table</summary>
    <table id="chart-desc"><thead><tr><th>Month</th><th>Signups</th></tr></thead><tbody></tbody></table>
  </details>
</figure>

<script>
const data = [
  { label: "Jan", value: 420 }, { label: "Feb", value: 380 },
  { label: "Mar", value: 510 }, { label: "Apr", value: 640 },
  { label: "May", value: 590 }, { label: "Jun", value: 720 },
  { label: "Jul", value: 810 }, { label: "Aug", value: 760 },
  { label: "Sep", value: 690 }, { label: "Oct", value: 880 },
];

const root    = document.getElementById("viz");
const canvas  = document.getElementById("chart");
const tooltip = document.getElementById("tooltip");
const ctx     = canvas.getContext("2d");
const M = { top: 24, right: 8, bottom: 32, left: 48 };
const FONT = '12px system-ui, -apple-system, "Segoe UI", sans-serif';

let hover = -1;
let layout = null;

// Round the axis max up to 1/2/5 × 10^n so ticks land on clean numbers.
function niceMax(v) {
  const p = 10 ** Math.floor(Math.log10(v));
  const n = v / p;
  return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * p;
}

function draw() {
  const css = getComputedStyle(root);
  const c = (name) => css.getPropertyValue(name).trim();

  // Crisp on HiDPI screens: size the backing store in device pixels.
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.clientWidth, h = canvas.clientHeight;
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);

  const pw = w - M.left - M.right;
  const ph = h - M.top - M.bottom;
  const max = niceMax(Math.max(...data.map(d => d.value)));
  const ticks = 4;
  const y = (v) => M.top + ph - (v / max) * ph;
  const band = pw / data.length;
  const barW = Math.max(4, Math.min(band * 0.62, 44));
  layout = { band, pw, ph, y };

  ctx.font = FONT;

  // Recessive gridlines + y tick labels.
  ctx.textAlign = "right";
  ctx.textBaseline = "middle";
  for (let i = 1; i <= ticks; i++) {
    const v = (max * i) / ticks;
    const yy = Math.round(y(v)) + 0.5;
    ctx.strokeStyle = c("--grid");
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(M.left, yy);
    ctx.lineTo(M.left + pw, yy);
    ctx.stroke();
    ctx.fillStyle = c("--text-muted");
    ctx.fillText(v.toLocaleString(), M.left - 8, yy);
  }
  ctx.fillText("0", M.left - 8, y(0));

  // Hover band: full-column highlight, which is also the hit target.
  if (hover >= 0) {
    ctx.fillStyle = c("--hover-band");
    ctx.fillRect(M.left + hover * band, M.top, band, ph);
  }

  // Bars: 4px rounded data-end, square at the baseline.
  const peak = data.reduce((best, d, i) => (d.value > data[best].value ? i : best), 0);
  data.forEach((d, i) => {
    const x = M.left + i * band + (band - barW) / 2;
    const top = y(d.value);
    ctx.fillStyle = c("--series-1");
    ctx.globalAlpha = hover >= 0 && hover !== i ? 0.55 : 1;
    ctx.beginPath();
    ctx.roundRect(x, top, barW, y(0) - top, [4, 4, 0, 0]);
    ctx.fill();
    ctx.globalAlpha = 1;

    // x-axis category label
    ctx.fillStyle = c("--text-secondary");
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    ctx.fillText(d.label, x + barW / 2, M.top + ph + 8);

    // Selective direct label: only the peak, in text ink (not series color).
    if (i === peak) {
      ctx.fillStyle = c("--text-primary");
      ctx.textBaseline = "bottom";
      ctx.fillText(d.value.toLocaleString(), x + barW / 2, top - 6);
    }
  });

  // Baseline drawn last so it sits over the bar bottoms.
  const by = Math.round(y(0)) + 0.5;
  ctx.strokeStyle = c("--text-muted");
  ctx.beginPath();
  ctx.moveTo(M.left, by);
  ctx.lineTo(M.left + pw, by);
  ctx.stroke();

  updateTooltip();
}

function updateTooltip() {
  if (hover < 0 || !layout) { tooltip.style.opacity = 0; return; }
  const d = data[hover];
  tooltip.innerHTML = `<span class="k">${d.label}</span> &nbsp;<span class="v">${d.value.toLocaleString()}</span>`;
  const left = canvas.offsetLeft + M.left + (hover + 0.5) * layout.band;
  const top  = canvas.offsetTop + layout.y(d.value);
  tooltip.style.left = `${left}px`;
  tooltip.style.top  = `${top}px`;
  tooltip.style.opacity = 1;
}

function setHover(i) {
  if (i !== hover) { hover = i; draw(); }
}

canvas.addEventListener("pointermove", (e) => {
  if (!layout) return;
  const r = canvas.getBoundingClientRect();
  const x = e.clientX - r.left - M.left;
  const i = Math.floor(x / layout.band);
  setHover(x >= 0 && i < data.length ? i : -1);
});
canvas.addEventListener("pointerleave", () => setHover(-1));

// Keyboard: arrow keys step through bars.
canvas.addEventListener("keydown", (e) => {
  if (e.key === "ArrowRight") setHover(Math.min(data.length - 1, hover + 1));
  else if (e.key === "ArrowLeft") setHover(Math.max(0, hover < 0 ? 0 : hover - 1));
  else if (e.key === "Escape") setHover(-1);
  else return;
  e.preventDefault();
});
canvas.addEventListener("blur", () => setHover(-1));

// Table view (accessible fallback).
document.querySelector("#chart-desc tbody").innerHTML = data
  .map(d => `<tr><td>${d.label}</td><td>${d.value.toLocaleString()}</td></tr>`)
  .join("");

new ResizeObserver(draw).observe(canvas);
matchMedia("(prefers-color-scheme: dark)").addEventListener("change", draw);
new MutationObserver(draw).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
</script>
</body>
</html>
```

**How it's built:**
- **Sharp on high-resolution screens:** the canvas is sized using `devicePixelRatio`, and it redraws whenever it's resized.
- **Bars:** each bar has a 4px rounded top and a square bottom on the baseline. They're thin and well spaced, under clean 1/2/5 tick values with light gridlines.
- **Colors:** one series, so it uses the first color of the skill's default palette (blue). The canvas reads colors from CSS variables, so dark mode has its own colors and redraws when the system setting or a `data-theme` attribute changes.
- **Labels:** only the tallest bar shows its value, in normal text color. There's no legend box because the title names the single series.
- **Interaction:** hovering anywhere in a bar's column highlights it, dims the others and shows a tooltip. Arrow keys step through the bars and Escape clears.
- **Accessibility:** the canvas has `role="img"` with a label, and a "View as table" section lists the same data.

To use your own data, replace the `data` array. To use your brand's color, change `--series-1` in both the light and dark blocks.

There's no game code in this directory, only a WebGPU skill, and it doesn't cover native Vulkan. So this is a general setup guide. I've written it for macOS, where you're running, and noted what changes on Linux and Windows. If you share your engine's instance and device creation code, I can wire this in directly.

## 1. Install the SDK

Install the **LunarG Vulkan SDK** from vulkan.lunarg.com. On macOS it includes MoltenVK, the validation layer and `vkconfig`. Then set up your shell:

```sh
source ~/VulkanSDK/<version>/setup-env.sh   # sets VULKAN_SDK, VK_LAYER_PATH, VK_ICD_FILENAMES, DYLD paths
vulkaninfo --summary                         # should list VK_LAYER_KHRONOS_validation
```

Linux: install `vulkan-validationlayers` from your package manager. Windows: the SDK installer registers the layers for you.

## 2. Enable the layer in debug builds (C/C++)

```cpp
#ifndef NDEBUG
constexpr bool kEnableValidation = true;
#else
constexpr bool kEnableValidation = false;
#endif

const char* kValidationLayer = "VK_LAYER_KHRONOS_validation";

bool hasLayer(const char* name) {
    uint32_t n = 0;
    vkEnumerateInstanceLayerProperties(&n, nullptr);
    std::vector<VkLayerProperties> props(n);
    vkEnumerateInstanceLayerProperties(&n, props.data());
    for (auto& p : props) if (strcmp(p.layerName, name) == 0) return true;
    return false;
}

static VKAPI_ATTR VkBool32 VKAPI_CALL debugCallback(
    VkDebugUtilsMessageSeverityFlagBitsEXT severity,
    VkDebugUtilsMessageTypeFlagsEXT,
    const VkDebugUtilsMessengerCallbackDataEXT* data, void*) {
    if (severity >= VK_DEBUG_UTILS_MESSAGE_SEVERITY_WARNING_BIT_EXT)
        fprintf(stderr, "[vulkan] %s\n", data->pMessage);
    return VK_FALSE;  // never abort the call
}

VkDebugUtilsMessengerCreateInfoEXT messengerInfo{
    .sType = VK_STRUCTURE_TYPE_DEBUG_UTILS_MESSENGER_CREATE_INFO_EXT,
    .messageSeverity = VK_DEBUG_UTILS_MESSAGE_SEVERITY_WARNING_BIT_EXT |
                       VK_DEBUG_UTILS_MESSAGE_SEVERITY_ERROR_BIT_EXT,
    .messageType = VK_DEBUG_UTILS_MESSAGE_TYPE_GENERAL_BIT_EXT |
                   VK_DEBUG_UTILS_MESSAGE_TYPE_VALIDATION_BIT_EXT |
                   VK_DEBUG_UTILS_MESSAGE_TYPE_PERFORMANCE_BIT_EXT,
    .pfnUserCallback = debugCallback,
};

std::vector<const char*> layers, exts = /* from glfwGetRequiredInstanceExtensions / SDL_Vulkan_GetInstanceExtensions */;
VkInstanceCreateFlags flags = 0;

#ifdef __APPLE__   // MoltenVK is a "portability" driver; without this, vkCreateInstance returns VK_ERROR_INCOMPATIBLE_DRIVER
exts.push_back(VK_KHR_PORTABILITY_ENUMERATION_EXTENSION_NAME);
flags |= VK_INSTANCE_CREATE_ENUMERATE_PORTABILITY_BIT_KHR;
#endif

if (kEnableValidation && hasLayer(kValidationLayer)) {
    layers.push_back(kValidationLayer);
    exts.push_back(VK_EXT_DEBUG_UTILS_EXTENSION_NAME);
}

VkInstanceCreateInfo ci{
    .sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO,
    .pNext = kEnableValidation ? &messengerInfo : nullptr,  // also catches errors inside vkCreate/DestroyInstance
    .flags = flags,
    .pApplicationInfo = &appInfo,
    .enabledLayerCount = (uint32_t)layers.size(),
    .ppEnabledLayerNames = layers.data(),
    .enabledExtensionCount = (uint32_t)exts.size(),
    .ppEnabledExtensionNames = exts.data(),
};
vkCreateInstance(&ci, nullptr, &instance);

// Create the persistent messenger. It's an extension function, so load it first:
auto create = (PFN_vkCreateDebugUtilsMessengerEXT)
    vkGetInstanceProcAddr(instance, "vkCreateDebugUtilsMessengerEXT");
create(instance, &messengerInfo, nullptr, &messenger);
// Destroy it with vkDestroyDebugUtilsMessengerEXT before vkDestroyInstance.
```

On macOS, also enable `VK_KHR_portability_subset` as a **device** extension whenever the physical device advertises it.

## 3. Optional extra checks

You can turn these on in code with `VkValidationFeaturesEXT` chained into `pNext`, or with `vkconfig` (step 4) and no code changes:

| Feature | What it catches | Cost |
|---|---|---|
| Synchronization validation | Missing barriers, read/write hazards | Moderate. Turn it on regularly. |
| GPU-assisted validation | Out-of-bounds descriptor indexing, bindless bugs | Heavy |
| Best practices | Performance and portability warnings | Low, but noisy |
| Debug printf | `debugPrintfEXT` output from shaders | Moderate |

Leave GPU-assisted validation and debug printf off by default, because they conflict with each other.

## 4. Configure without recompiling

- **`vkconfig`** (Vulkan Configurator GUI): pick the layers and settings and toggle the extra checks. It applies them to every Vulkan app while it's running, which is handy for builds you can't change.
- **Environment variables**, useful for CI or a quick test:
  ```sh
  VK_INSTANCE_LAYERS=VK_LAYER_KHRONOS_validation \
  VK_VALIDATION_VALIDATE_SYNC=true \
  VK_LOADER_DEBUG=error,warn ./MyGame
  ```
- **`vk_layer_settings.txt`** in the working directory, or pointed to by `VK_LAYER_SETTINGS_PATH`. Use it to silence specific known-noisy message IDs (`khronos_validation.message_id_filter = ...`).

## 5. Habits that pay off

- **Name your objects** with `vkSetDebugUtilsObjectNameEXT`. Validation messages then say "texture 'PlayerAlbedo'" instead of printing a raw handle.
- **Break on errors:** put a breakpoint (or `__builtin_trap()` in debug builds) in the callback when severity is ERROR. The call stack then points at the API call that caused it.
- **Fix the first error first.** Later errors often cascade from it.
- **Never ship with validation on.** It costs a lot of CPU time, and the layer isn't installed on players' machines. The `hasLayer` check means a debug build still runs on a machine without the SDK.
- **Test on real drivers too.** MoltenVK only covers part of Vulkan, so a clean validation run on a Mac doesn't guarantee correct behaviour on desktop drivers. Validate on Windows or Linux as well.

