**What's wrong:** In development, React Strict Mode mounts the effect, runs its cleanup, then mounts it again. Your cleanup runs while the first `init()` is still waiting on `requestDevice()`. At that point `device` is still `undefined`, so `device?.destroy()` does nothing. The first `init()` then finishes, keeps its device and starts a frame loop that nothing stops. That's the second device, and the leak. The same thing can happen in production if the component unmounts during setup.

**The fix:** Cleanup sets a `cancelled` flag, and setup checks it after each `await`. If cleanup has already run, setup destroys the device it just got and stops before starting the loop.

```tsx
'use client'
import { useEffect, useRef } from 'react'
import { createScene } from './scene'

export function GpuCanvas() {
  const ref = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = ref.current
    if (!canvas || !navigator.gpu) return

    // Strict Mode runs cleanup while setup may still be awaiting. Every await
    // checks this flag so a cancelled run never keeps a device or a frame loop.
    let cancelled = false
    let raf = 0
    let device: GPUDevice | undefined

    async function init(canvas: HTMLCanvasElement) {
      const adapter = await navigator.gpu.requestAdapter()
      if (!adapter || cancelled) return
      const d = await adapter.requestDevice()
      // Cleanup already ran during the await. Do not leak the device.
      if (cancelled) return d.destroy()
      device = d

      const context = canvas.getContext('webgpu')
      if (!context) return
      const format = navigator.gpu.getPreferredCanvasFormat()
      context.configure({ device: d, format })
      const scene = await createScene(d, format)
      if (cancelled) return

      const frame = () => {
        const encoder = d.createCommandEncoder()
        scene.encode(encoder, context.getCurrentTexture())
        d.queue.submit([encoder.finish()])
        raf = requestAnimationFrame(frame)
      }
      raf = requestAnimationFrame(frame)
    }
    init(canvas).catch((err) => console.error('WebGPU setup failed', err))

    return () => {
      cancelled = true
      cancelAnimationFrame(raf)
      device?.destroy()
    }
  }, [])

  return <canvas ref={ref} className="h-full w-full" />
}
```

