  const cameraLayout = device.createBindGroupLayout({
    label: 'camera',
    entries: [
      { binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } },
    ],
  })
  const layout = device.createPipelineLayout({ label: 'scene', bindGroupLayouts: [cameraLayout] })

  const [mesh, outline] = await Promise.all([
    device.createRenderPipelineAsync({
      label: 'mesh',
      layout,
      vertex: { module, entryPoint: 'vsMesh' },
      fragment: { module, entryPoint: 'fsMesh', targets: [{ format }] },
    }),
    device.createRenderPipelineAsync({
      label: 'outline',
      layout,
      vertex: { module, entryPoint: 'vsOutline' },
      fragment: { module, entryPoint: 'fsOutline', targets: [{ format }] },
    }),
  ]).catch((err: unknown) => {
    throw new Error(`pipeline creation failed: ${String(err)}`)
  })

  const camera = device.createBindGroup({
    label: 'camera',
    layout: cameraLayout,
    entries: [{ binding: 0, resource: { buffer: cameraBuffer } }],
  })
  return { mesh, outline, camera }
