### Suggested `src/init.ts`

```ts
export type GpuInit =
  | { kind: 'webgpu'; device: GPUDevice; context: GPUCanvasContext; hasF16: boolean; hasTimestamps: boolean }
  | { kind: 'unsupported'; reason: string }

const wanted: GPUFeatureName[] = ['shader-f16', 'timestamp-query']

export async function initGpu(canvas: HTMLCanvasElement): Promise<GpuInit> {
  if (!('gpu' in navigator)) {
    return { kind: 'unsupported', reason: isSecureContext ? 'no navigator.gpu' : 'not a secure context' }
  }
  const adapter = await navigator.gpu.requestAdapter({ powerPreference: 'high-performance' })
  if (!adapter) return { kind: 'unsupported', reason: 'no adapter' }

  let device: GPUDevice
  try {
    device = await adapter.requestDevice({
      label: 'app',
      requiredFeatures: wanted.filter((f) => adapter.features.has(f)),
    })
  } catch (err: unknown) {
    return { kind: 'unsupported', reason: err instanceof Error ? err.message : String(err) }
  }

  device.addEventListener('uncapturederror', (e) => console.error('WebGPU:', e.error.message))
  device.lost.then((info) => {
    if (info.reason !== 'destroyed') console.error('WebGPU device lost:', info.message)
    // Recovery: request a NEW adapter, then rebuild everything. The old adapter can't make another device.
  })

  const context = canvas.getContext('webgpu')
  if (!context) return { kind: 'unsupported', reason: 'no webgpu canvas context' }
  context.configure({ device, format: navigator.gpu.getPreferredCanvasFormat(), alphaMode: 'opaque' })

  return {
    kind: 'webgpu',
    device,
    context,
    hasF16: device.features.has('shader-f16'),
    hasTimestamps: device.features.has('timestamp-query'),
  }
}
```

