I don't have a file-writing tool in this session, so the code is below for you to save yourself. It's a separable Gaussian blur that runs as two passes.

**Passes:**
1. **Horizontal:** reads the `input` texture and writes the `blur.tmp` texture.
2. **Vertical:** reads `blur.tmp` and writes the `blur.out` texture.

`blur.out` holds the blurred image. Both passes use the same pipeline with different bind groups. The kernel has `2r+1` taps per pass, compared with `(2r+1)²` for a single-pass 2D kernel.

### `blur.wgsl`

```wgsl
struct Params {
  dir: vec2i,     // (1, 0) horizontal, (0, 1) vertical
  radius: i32,
  sigma: f32,
}

@group(0) @binding(0) var src: texture_2d<f32>;
@group(0) @binding(1) var dst: texture_storage_2d<rgba8unorm, write>;
@group(0) @binding(2) var<uniform> params: Params;

override WG_X: u32 = 8;
override WG_Y: u32 = 8;

@compute @workgroup_size(WG_X, WG_Y)
fn blur(@builtin(global_invocation_id) id: vec3u) {
  let size = vec2i(textureDimensions(src));
  let p = vec2i(id.xy);
  // The dispatch is rounded up, so edge workgroups run past the image.
  if (p.x >= size.x || p.y >= size.y) { return; }

  let k = -0.5 / (params.sigma * params.sigma);
  var sum = vec4f(0.0);
  var wsum = 0.0;
  for (var i = -params.radius; i <= params.radius; i++) {
    // Clamp to edge so borders don't darken.
    let q = clamp(p + params.dir * i, vec2i(0), size - 1);
    let w = exp(f32(i * i) * k);
    let c = textureLoad(src, q, 0);
    // Premultiply so transparent pixels don't bleed their color into neighbors.
    sum += vec4f(c.rgb * c.a, c.a) * w;
    wsum += w;
  }

  let avg = sum / wsum;
  let rgb = select(vec3f(0.0), avg.rgb / avg.a, avg.a > 0.0);
  textureStore(dst, p, vec4f(rgb, avg.a));
}
```

### `blur.ts`

```ts
import BLUR_WGSL from './blur.wgsl?raw' // or inline the string

const WG = 8
const MAX_RADIUS = 64 // very large kernels can hit the OS GPU timeout and lose the device

export async function createBlur(device: GPUDevice) {
  const module = device.createShaderModule({ label: 'blur.shader', code: BLUR_WGSL })

  const bindGroupLayout = device.createBindGroupLayout({
    label: 'blur.bgl',
    entries: [
      { binding: 0, visibility: GPUShaderStage.COMPUTE, texture: { sampleType: 'float' } },
      { binding: 1, visibility: GPUShaderStage.COMPUTE, storageTexture: { access: 'write-only', format: 'rgba8unorm' } },
      { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: 'uniform' } },
    ],
  })

  // Rejects with GPUPipelineError rather than raising a device error; the caller catches it.
  const pipeline = await device.createComputePipelineAsync({
    label: 'blur.pipeline',
    layout: device.createPipelineLayout({ label: 'blur.layout', bindGroupLayouts: [bindGroupLayout] }),
    compute: { module, entryPoint: 'blur', constants: { WG_X: WG, WG_Y: WG } },
  })

  // Params layout: dir vec2i @0, radius i32 @8, sigma f32 @12, 16 bytes total.
  function createParams(label: string, dx: number, dy: number, radius: number, sigma: number) {
    const data = new ArrayBuffer(16)
    new Int32Array(data, 0, 3).set([dx, dy, radius])
    new Float32Array(data, 12, 1)[0] = sigma
    const buffer = device.createBuffer({ label, size: 16, usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST })
    device.queue.writeBuffer(buffer, 0, data)
    return buffer
  }

  function createBindGroup(label: string, from: GPUTexture, to: GPUTexture, params: GPUBuffer) {
    return device.createBindGroup({
      label,
      layout: bindGroupLayout,
      entries: [
        { binding: 0, resource: from.createView() },
        { binding: 1, resource: to.createView() },
        { binding: 2, resource: { buffer: params } },
      ],
    })
  }

  /** Blurs `src` (rgba8unorm, TEXTURE_BINDING) and returns a new texture. The caller destroys it. */
  function blur(src: GPUTexture, radius: number): GPUTexture {
    const r = Math.max(0, Math.min(MAX_RADIUS, Math.round(radius)))
    const sigma = Math.max(r / 3, 0.5) // ±3σ covers ~99.7% of the Gaussian
    const size = [src.width, src.height]
    const usage = GPUTextureUsage.STORAGE_BINDING | GPUTextureUsage.TEXTURE_BINDING

    const tmp = device.createTexture({ label: 'blur.tmp', size, format: 'rgba8unorm', usage })
    const out = device.createTexture({
      label: 'blur.out', size, format: 'rgba8unorm', usage: usage | GPUTextureUsage.COPY_SRC,
    })
    const hParams = createParams('blur.params.h', 1, 0, r, sigma)
    const vParams = createParams('blur.params.v', 0, 1, r, sigma)

    const encoder = device.createCommandEncoder({ label: 'blur.encoder' })
    const pass = encoder.beginComputePass({ label: 'blur.pass' })
    pass.setPipeline(pipeline)
    const gx = Math.ceil(src.width / WG)
    const gy = Math.ceil(src.height / WG)
    // Writes from dispatch 1 are visible to dispatch 2 in the same pass.
    pass.setBindGroup(0, createBindGroup('blur.bg.h', src, tmp, hParams))
    pass.dispatchWorkgroups(gx, gy)
    pass.setBindGroup(0, createBindGroup('blur.bg.v', tmp, out, vParams))
    pass.dispatchWorkgroups(gx, gy)
    pass.end()
    device.queue.submit([encoder.finish()])

    // Destruction is deferred until the submitted work finishes.
    tmp.destroy()
    hParams.destroy()
    vParams.destroy()
    return out
  }

  return { blur }
}

export async function loadTexture(device: GPUDevice, url: string): Promise<GPUTexture> {
  const blob = await (await fetch(url)).blob()
  const bitmap = await createImageBitmap(blob, { colorSpaceConversion: 'none' })
  const texture = device.createTexture({
    label: 'blur.input',
    size: [bitmap.width, bitmap.height],
    format: 'rgba8unorm',
    // copyExternalImageToTexture requires RENDER_ATTACHMENT and COPY_DST.
    usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST | GPUTextureUsage.RENDER_ATTACHMENT,
  })
  device.queue.copyExternalImageToTexture({ source: bitmap }, { texture }, [bitmap.width, bitmap.height])
  bitmap.close()
  return texture
}

export async function toImageData(device: GPUDevice, texture: GPUTexture): Promise<ImageData> {
  const { width, height } = texture
  const bytesPerRow = Math.ceil((width * 4) / 256) * 256 // copy rows must be 256-byte aligned
  const buffer = device.createBuffer({
    label: 'blur.readback', size: bytesPerRow * height,
    usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
  })
  const encoder = device.createCommandEncoder({ label: 'blur.readback' })
  encoder.copyTextureToBuffer({ texture }, { buffer, bytesPerRow }, [width, height])
  device.queue.submit([encoder.finish()])

  await buffer.mapAsync(GPUMapMode.READ)
  const padded = new Uint8Array(buffer.getMappedRange())
  const pixels = new Uint8ClampedArray(width * height * 4)
  for (let y = 0; y < height; y++) {
    pixels.set(padded.subarray(y * bytesPerRow, y * bytesPerRow + width * 4), y * width * 4)
  }
  buffer.unmap()
  buffer.destroy()
  return new ImageData(pixels, width, height)
}
```

### Usage

```ts
async function main(canvas: HTMLCanvasElement, url: string, radius: number) {
  const adapter = await navigator.gpu?.requestAdapter()
  if (!adapter) throw new Error('WebGPU not available') // fall back to a CSS filter: blur() or canvas 2D
  const device = await adapter.requestDevice()

  device.addEventListener('uncapturederror', (e) => console.error('WebGPU:', e.error.message))
  device.lost.then((info) => {
    if (info.reason !== 'destroyed') console.warn('Device lost, retrying:', info.message)
    // Recovery needs a new adapter, so rerun main (add a retry cap in production).
    if (info.reason !== 'destroyed') void main(canvas, url, radius)
  })

  const { blur } = await createBlur(device)
  const input = await loadTexture(device, url)
  const output = blur(input, radius)
  const image = await toImageData(device, output)

  canvas.width = image.width
  canvas.height = image.height
  canvas.getContext('2d')!.putImageData(image, 0, 0)

  input.destroy()
  output.destroy()
}
```

### Design choices
- **No sampler:** the shader uses `textureLoad` with clamp-to-edge.
- **Workgroups:** they're 8×8, set through `override` constants so you can try other sizes. The dispatch count rounds up, and the shader bounds-checks pixels past the image edge.
- **Transparency:** each pass premultiplies alpha and then reverses it, so transparent pixels don't leave dark or colored halos.
- **Radius limit:** the radius is capped at 64 because very large kernels can run long enough to hit the system GPU timeout and lose the device.
- **Gamma:** the blur runs on the stored sRGB values. If you want a physically correct (linear) blur, convert with `pow(c, 2.2)` before the weighted sum and back afterwards. Storage textures can't use `rgba8unorm-srgb`, so the browser won't do this conversion for you.
- **Large radii:** if you need large radii fast, the next step is caching a row tile in `var<workgroup>` memory. The simple version here is usually fine up to radius ~20 on typical images.

**Not tested:** nothing above has been compiled, run on a GPU, or tried in a browser. I didn't run the WGSL through a validator like `naga` or Tint, and I worked out the 16-byte `Params` offsets by hand instead of with the skill's layout script. Before relying on it, paste it into a page in Chrome and check the console for validation errors.

