import { create, globals } from 'webgpu'
import { afterAll, afterEach, beforeAll, describe, expect, test } from 'vitest'
import { readFileSync } from 'node:fs'

Object.assign(globalThis, globals) // GPUBufferUsage, GPUMapMode, ...

const adapter = await create([]).requestAdapter()
const WGSL = readFileSync(new URL('../src/shaders/compute.wgsl', import.meta.url), 'utf8')

// CI machines often have no GPU: skip clearly instead of failing.
describe.skipIf(!adapter)('compute shader', () => {
  let device: GPUDevice
  const gpuErrors: string[] = []

  beforeAll(async () => {
    device = await adapter!.requestDevice({ label: 'test device' })
    // Throwing inside the listener wouldn't fail the test, so collect errors and assert on them.
    device.addEventListener('uncapturederror', (e) => {
      gpuErrors.push((e as GPUUncapturedErrorEvent).error.message)
    })
  })
  afterEach(() => expect(gpuErrors.splice(0)).toEqual([]))
  afterAll(() => device?.destroy())

  async function run(input: Float32Array): Promise<Float32Array> {
    const module = device.createShaderModule({ label: 'compute', code: WGSL })
    const info = await module.getCompilationInfo()
    const errors = info.messages.filter((m) => m.type === 'error')
    expect(errors.map((m) => `${m.lineNum}:${m.linePos} ${m.message}`)).toEqual([])

    const pipeline = await device.createComputePipelineAsync({
      label: 'compute pipeline',
      layout: 'auto',
      compute: { module, entryPoint: 'main' },
    })

    const data = device.createBuffer({
      label: 'data',
      size: input.byteLength,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
    })
    device.queue.writeBuffer(data, 0, input)

    const readback = device.createBuffer({
      label: 'readback',
      size: input.byteLength,
      usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
    })

    const bindGroup = device.createBindGroup({
      label: 'compute bind group',
      layout: pipeline.getBindGroupLayout(0),
      entries: [{ binding: 0, resource: { buffer: data } }],
    })

    const WORKGROUP_SIZE = 64 // must match @workgroup_size in the shader
    const encoder = device.createCommandEncoder({ label: 'compute encoder' })
    const pass = encoder.beginComputePass({ label: 'compute pass' })
    pass.setPipeline(pipeline)
    pass.setBindGroup(0, bindGroup)
    pass.dispatchWorkgroups(Math.ceil(input.length / WORKGROUP_SIZE))
    pass.end()
    encoder.copyBufferToBuffer(data, 0, readback, 0, input.byteLength)
    device.queue.submit([encoder.finish()])

    await readback.mapAsync(GPUMapMode.READ)
    const out = new Float32Array(readback.getMappedRange().slice(0))
    readback.unmap()
    data.destroy()
    readback.destroy()
    return out
  }

  test('processes every element, including a partial last workgroup', async () => {
    const n = 1000 // deliberately not a multiple of 64
    const input = Float32Array.from({ length: n }, (_, i) => i)
    const out = await run(input)
    for (let i = 0; i < n; i++) {
      expect(out[i]).toBeCloseTo(i * 2, 5) // replace with your shader's expected result
    }
  })
})
