  <div class="wrap">
    <canvas id="chart" role="img" aria-label="Bar chart of monthly signups in 2026"></canvas>
    <div class="tip" id="tip"></div>
  </div>
  <details><summary>Show data table</summary><table id="table"></table></details>

<script>
const data = [
  { label: "Jan", value: 420 }, { label: "Feb", value: 380 }, { label: "Mar", value: 510 },
  { label: "Apr", value: 640 }, { label: "May", value: 590 }, { label: "Jun", value: 720 },
  { label: "Jul", value: 810 }, { label: "Aug", value: 760 }, { label: "Sep", value: 690 },
  { label: "Oct", value: 880 },
];

const canvas = document.getElementById("chart");
const ctx = canvas.getContext("2d");
const tip = document.getElementById("tip");
const pad = { top: 16, right: 8, bottom: 32, left: 48 };
let bars = [], hover = -1;

const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();

// Round the axis max up to a 1/2/5 × 10^n step so gridlines land on whole numbers.
function niceTicks(max, count = 5) {
  const raw = max / count, mag = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 5, 10].map((m) => m * mag).find((s) => s >= raw);
  const top = Math.ceil(max / step) * step;
  return Array.from({ length: top / step + 1 }, (_, i) => i * step);
}

function draw() {
  const dpr = window.devicePixelRatio || 1;
  const { width: w, height: h } = canvas.getBoundingClientRect();
  canvas.width = w * dpr; canvas.height = h * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);

  const plotW = w - pad.left - pad.right, plotH = h - pad.top - pad.bottom;
  const ticks = niceTicks(Math.max(...data.map((d) => d.value)));
  const yMax = ticks.at(-1);
  const y = (v) => pad.top + plotH - (v / yMax) * plotH;

  // Recessive gridlines + y labels
  ctx.font = "12px system-ui, sans-serif";
  ctx.textAlign = "right"; ctx.textBaseline = "middle";
  ticks.forEach((t) => {
    ctx.strokeStyle = css("--grid"); ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(pad.left, Math.round(y(t)) + 0.5);
    ctx.lineTo(w - pad.right, Math.round(y(t)) + 0.5); ctx.stroke();
    ctx.fillStyle = css("--text-secondary");
    ctx.fillText(t.toLocaleString(), pad.left - 8, y(t));
  });

  // Bars: thin-ish (60% of band), 4px rounded top, square at baseline
  const band = plotW / data.length, barW = Math.max(4, band * 0.6);
  bars = data.map((d, i) => {
    const x = pad.left + i * band + (band - barW) / 2, top = y(d.value);
    return { x, y: top, w: barW, h: y(0) - top, band: [pad.left + i * band, band] };
  });

  bars.forEach((b, i) => {
    ctx.fillStyle = css("--series-1");
    ctx.globalAlpha = hover === -1 || hover === i ? 1 : 0.45;
    ctx.beginPath();
    ctx.roundRect(b.x, b.y, b.w, b.h, [4, 4, 0, 0]);
    ctx.fill();
  });
  ctx.globalAlpha = 1;

  // X labels
  ctx.fillStyle = css("--text-secondary");
  ctx.textAlign = "center"; ctx.textBaseline = "top";
  data.forEach((d, i) => ctx.fillText(d.label, bars[i].x + barW / 2, y(0) + 8));

  // Baseline
  ctx.strokeStyle = css("--text-secondary");
  ctx.beginPath(); ctx.moveTo(pad.left, Math.round(y(0)) + 0.5);
  ctx.lineTo(w - pad.right, Math.round(y(0)) + 0.5); ctx.stroke();
}

// Hover: the whole column band is the hit target, not just the bar
canvas.addEventListener("mousemove", (e) => {
  const r = canvas.getBoundingClientRect(), mx = e.clientX - r.left;
  const i = bars.findIndex((b) => mx >= b.band[0] && mx < b.band[0] + b.band[1]);
  if (i !== hover) { hover = i; draw(); }
  if (i === -1) { tip.style.display = "none"; return; }
  const b = bars[i];
  tip.innerHTML = `<strong>${data[i].label}</strong> · ${data[i].value.toLocaleString()}`;
  tip.style.left = `${b.x + b.w / 2}px`; tip.style.top = `${b.y}px`;
  tip.style.display = "block";
});
canvas.addEventListener("mouseleave", () => { hover = -1; tip.style.display = "none"; draw(); });

// Table view for screen readers and anyone who wants exact numbers
document.getElementById("table").innerHTML =
  "<tr><th>Month</th><th>Signups</th></tr>" +
  data.map((d) => `<tr><td>${d.label}</td><td>${d.value.toLocaleString()}</td></tr>`).join("");

new ResizeObserver(draw).observe(canvas);
matchMedia("(prefers-color-scheme: dark)").addEventListener("change", draw);
</script>
</body>
</html>
```

