The fastest way is to skip copying entirely. `device.importExternalTexture({ source: video })` wraps the current video frame as a `texture_external`, and the shader reads it with `textureSampleBaseClampToEdge`. The catch is that the external texture expires shortly after you import it. So you import it and build its bind group **in every frame**, never once at setup.

```ts
// video-to-webgpu.ts
const shader = /* wgsl */ `
struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) uv: vec2f,
};

// One triangle that covers the whole screen. No vertex buffer needed.
@vertex
fn vs(@builtin(vertex_index) i: u32) -> VSOut {
  let p = array(vec2f(-1, -1), vec2f(3, -1), vec2f(-1, 3))[i];
  var o: VSOut;
  o.pos = vec4f(p, 0, 1);
  o.uv = vec2f(p.x * 0.5 + 0.5, 0.5 - p.y * 0.5); // flip Y: video row 0 is the top
  return o;
}

@group(0) @binding(0) var videoTex: texture_external;
@group(0) @binding(1) var videoSampler: sampler;

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  return textureSampleBaseClampToEdge(videoTex, videoSampler, in.uv);
}
`;

export async function playVideoOnCanvas(canvas: HTMLCanvasElement, video: HTMLVideoElement) {
  // ---- Setup, with a fallback for every way it can fail ----
  if (!navigator.gpu) return fallback(canvas, video, 'navigator.gpu missing');
  const adapter = await navigator.gpu.requestAdapter();
  if (!adapter) return fallback(canvas, video, 'no GPU adapter');
  const device = await adapter.requestDevice({ label: 'video device' });

  device.addEventListener('uncapturederror', (e) =>
    console.error('WebGPU error:', (e as GPUUncapturedErrorEvent).error.message));

  let stopped = false;
  device.lost.then((info) => {
    console.warn(`WebGPU device lost (${info.reason}): ${info.message}`);
    // Not lost on purpose: start over with a new adapter and device.
    if (!stopped && info.reason !== 'destroyed') playVideoOnCanvas(canvas, video);
  });

  const context = canvas.getContext('webgpu')!;
  const format = navigator.gpu.getPreferredCanvasFormat();
  context.configure({ device, format, alphaMode: 'opaque' });

  // ---- Objects created once ----
  // Explicit layout, because external textures need an `externalTexture` entry
  const bindGroupLayout = device.createBindGroupLayout({
    label: 'video BGL',
    entries: [
      { binding: 0, visibility: GPUShaderStage.FRAGMENT, externalTexture: {} },
      { binding: 1, visibility: GPUShaderStage.FRAGMENT, sampler: {} },
    ],
  });
  const module = device.createShaderModule({ label: 'video shader', code: shader });
  const pipeline = await device.createRenderPipelineAsync({
    label: 'video pipeline',
    layout: device.createPipelineLayout({ label: 'video PL', bindGroupLayouts: [bindGroupLayout] }),
    vertex: { module, entryPoint: 'vs' },
    fragment: { module, entryPoint: 'fs', targets: [{ format }] },
    primitive: { topology: 'triangle-list' },
  });
  const sampler = device.createSampler({ label: 'video sampler', magFilter: 'linear', minFilter: 'linear' });

  // ---- Size the canvas in device pixels ----
  const resize = () => {
    const dpr = window.devicePixelRatio || 1;
    const max = device.limits.maxTextureDimension2D;
    canvas.width = Math.min(max, Math.max(1, Math.round(canvas.clientWidth * dpr)));
    canvas.height = Math.min(max, Math.max(1, Math.round(canvas.clientHeight * dpr)));
  };
  const ro = new ResizeObserver(resize);
  ro.observe(canvas);
  resize();

  // ---- Frame loop: import and bind every frame ----
  const hasRVFC = 'requestVideoFrameCallback' in HTMLVideoElement.prototype;
  const schedule = () =>
    hasRVFC ? video.requestVideoFrameCallback(frame) : requestAnimationFrame(frame);

  function frame() {
    if (stopped) return;
    if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) {
      const external = device.importExternalTexture({ label: 'video frame', source: video });
      const bindGroup = device.createBindGroup({
        label: 'video BG',
        layout: bindGroupLayout,
        entries: [
          { binding: 0, resource: external },
          { binding: 1, resource: sampler },
        ],
      });

      const encoder = device.createCommandEncoder({ label: 'video frame encoder' });
      const pass = encoder.beginRenderPass({
        label: 'video pass',
        colorAttachments: [{
          view: context.getCurrentTexture().createView(),
          loadOp: 'clear', storeOp: 'store', clearValue: [0, 0, 0, 1],
        }],
      });
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, bindGroup);
      pass.draw(3);
      pass.end();
      device.queue.submit([encoder.finish()]);
    }
    schedule();
  }
  schedule();

  // ---- Teardown ----
  return () => {
    stopped = true;
    ro.disconnect();
    context.unconfigure();
    device.destroy();
  };
}

function fallback(canvas: HTMLCanvasElement, video: HTMLVideoElement, why: string) {
  console.warn(`WebGPU unavailable (${why}); showing the <video> element instead.`);
  canvas.replaceWith(video);
  video.style.display = '';
  return () => {};
}
```

Usage:

```html
<canvas id="c" style="width:640px;height:360px"></canvas>
<video id="v" src="clip.mp4" muted loop playsinline crossorigin="anonymous" style="display:none"></video>
<script type="module">
  import { playVideoOnCanvas } from './video-to-webgpu.js';
  const video = document.getElementById('v');
  await video.play(); // browsers allow autoplay only when the video is muted
  const stop = await playVideoOnCanvas(document.getElementById('c'), video);
</script>
```

**Things to know:**
- **Frame timing:** `requestVideoFrameCallback` runs once for each new video frame, so nothing is redrawn while the video is paused. It falls back to `requestAnimationFrame` on browsers that don't have it. If you draw other animated content too, use `requestAnimationFrame` and import the video each frame there.
- **Cross-origin video:** the server must send CORS headers and the element needs `crossorigin="anonymous"`. Otherwise importing the frame fails with a security error.
- **Aspect ratio:** the video stretches to fill the canvas. To letterbox it, scale the UVs using `video.videoWidth / video.videoHeight` and the canvas aspect.
- **Keeping a frame:** if you need a normal `texture_2d` (for mipmaps, compute shaders, or a frame that outlives the current one), copy it with `device.queue.copyExternalImageToTexture({ source: video }, { texture }, [w, h])` instead. The destination texture needs `TEXTURE_BINDING | COPY_DST | RENDER_ATTACHMENT` usage. This makes a copy, so it is slower.
- **Device loss:** recovery starts over from a new adapter. Errors are logged through the `uncapturederror` listener, and every object has a label so error messages name it.

